import{_ as i,o,c as a,a2 as s}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"权限与安全：把信任边界配置清楚","description":"配置服务端密钥、浏览器会话、仓库访问、Webhook 和 MCP 网络边界，并按生产清单逐项核对。","frontmatter":{"page_id":"configuration-security","title":"权限与安全：把信任边界配置清楚","description":"配置服务端密钥、浏览器会话、仓库访问、Webhook 和 MCP 网络边界，并按生产清单逐项核对。"},"headers":[],"relativePath":"configuration/security.md","filePath":"configuration/security.md","lastUpdated":1786289447000}'),t={name:"configuration/security.md"};function d(c,e,l,r,p,h){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="权限与安全-把信任边界配置清楚" tabindex="-1">权限与安全：把信任边界配置清楚 <a class="header-anchor" href="#权限与安全-把信任边界配置清楚" aria-label="Permalink to &quot;权限与安全：把信任边界配置清楚&quot;">​</a></h1><p>Ershu 会接触代码仓库、登录状态和模型凭据。安全配置的重点不是打开某个总开关，而是分别限制浏览器、仓库、Webhook、MCP 和管理员操作的信任范围。</p><h2 id="保管四类服务端材料" tabindex="-1">保管四类服务端材料 <a class="header-anchor" href="#保管四类服务端材料" aria-label="Permalink to &quot;保管四类服务端材料&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>用途</th><th>更换后的影响</th></tr></thead><tbody><tr><td><code>SECRET_KEY</code></td><td>签署访问令牌和 CSRF 令牌</td><td>现有访问令牌和 CSRF 令牌失效</td></tr><tr><td><code>ENCRYPTION_KEY</code></td><td>加密数据库中的模型密钥、仓库凭据和登录材料</td><td>旧密文可能无法解密</td></tr><tr><td><code>MCP_KEY_PEPPER</code></td><td>为 MCP 密钥摘要提供数据库之外的服务端材料</td><td>所有现有 MCP 密钥失效</td></tr><tr><td><code>OPAQUE_SERVER_SETUP</code></td><td>维持密码注册与登录协议的服务端身份</td><td>更换后，现有密码记录可能无法继续登录</td></tr></tbody></table><p>前三项必须互不相同，每项至少 32 个字符，并且不能使用源码列出的弱值。它们都应由部署平台的密钥管理能力注入，不能写入仓库、镜像或公开日志。</p><p>开发环境可以让 API 首次启动时把 <code>OPAQUE_SERVER_SETUP</code> 生成并加密保存到数据库。生产环境必须显式提供稳定的值。当前代码只检查生产值的存在和基本强度，真正使用时还要能解码为正确的 OPAQUE 服务端材料；一串任意长文本并不够。</p><h2 id="保护浏览器会话" tabindex="-1">保护浏览器会话 <a class="header-anchor" href="#保护浏览器会话" aria-label="Permalink to &quot;保护浏览器会话&quot;">​</a></h2><p>生产环境至少需要以下设置：</p><div class="language-dotenv vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ENVIRONMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">production</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SESSION_COOKIE_SECURE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">true</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SESSION_COOKIE_SAMESITE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lax</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">CORS_ORIGINS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://ershu.example.org&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>具体域名必须换成真实前端来源。API 的浏览器保护分为三层：</p><ol><li>生产环境下，<code>/api/</code> 与 <code>/mcp</code> 请求必须表现为 HTTPS；否则返回 400。</li><li>携带会话 Cookie 的写请求必须同时提交有效的 <code>X-Ershu-CSRF</code> 请求头和 CSRF Cookie；请求带有 <code>Origin</code> 或 <code>Referer</code> 时，该来源还必须是当前站点或进入 <code>CORS_ORIGINS</code>，否则返回 403。</li><li>使用 <code>Authorization: Bearer ...</code> 的请求不依赖浏览器 Cookie，因此跳过 CSRF 检查，但仍要通过令牌认证和接口权限检查。</li></ol><p><code>SESSION_COOKIE_SAMESITE=none</code> 通常只适用于确实需要跨站 Cookie 的部署，并且仍要配合安全 Cookie 与准确的来源列表。不要用宽泛来源掩盖代理或域名配置错误。</p><p>若 HTTPS 在反向代理处终止，应只把实际代理地址写入 <code>FORWARDED_ALLOW_IPS</code>。API 依据请求方案判断是否为 HTTPS；转发头不可信或代理未正确传递方案时，会造成错误放行或错误拦截。</p><h2 id="限制远程-git-地址" tabindex="-1">限制远程 Git 地址 <a class="header-anchor" href="#限制远程-git-地址" aria-label="Permalink to &quot;限制远程 Git 地址&quot;">​</a></h2><p>默认允许的仓库地址形式只有：</p><ul><li><code>https://</code>；</li><li><code>ssh://</code>；</li><li><code>user@host:path</code> 形式的 SCP 风格 SSH 地址。</li></ul><p><code>http://</code> 和 <code>git://</code> 只有在 <code>ALLOW_INSECURE_GIT_URLS=true</code> 时才会通过，<code>file://</code> 只有在 <code>ALLOW_FILE_GIT_URLS=true</code> 时才会通过。这两个开关默认关闭，生产环境应继续关闭，除非已经评估并隔离相关风险。</p><p><code>GIT_ALLOWED_HOSTS</code> 控制远程主机范围：</p><ul><li>列表为空时，主机仍要能解析，并且默认拒绝回环、私有、链路本地、多播、保留和未指定地址；</li><li>列表非空时，不匹配的主机直接拒绝；</li><li>精确列入或匹配通配规则的主机可以解析到私有地址，但回环、链路本地等地址仍然拒绝；</li><li><code>*.example.org</code> 只匹配子域名，不匹配 <code>example.org</code> 本身。</li></ul><p>生产环境应列出实际 Git 服务主机，避免使用 <code>*</code>。主机检查发生在后续克隆和拉取前；修改列表不会重新审查已经存在的缓存内容。</p><h2 id="限制本地仓库路径" tabindex="-1">限制本地仓库路径 <a class="header-anchor" href="#限制本地仓库路径" aria-label="Permalink to &quot;限制本地仓库路径&quot;">​</a></h2><p>本地路径满足以下任一条件时，Core 才把它作为受信任工作区：</p><ul><li>位于 <code>REPOSITORY_STORAGE_PATH</code> 管理的缓存目录内；</li><li>位于 <code>TRUSTED_LOCAL_PATHS</code> 列出的目录或其子目录内；</li><li>目录本身包含 <code>.git</code>。</li></ul><p><code>ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS=true</code> 是开发环境的兜底入口，只在没有配置受信任路径列表、且环境不是生产时生效。生产校验会拒绝打开它。管理员仍应只添加明确需要分析的路径；受信任表示允许读取，不表示内容本身可信。</p><h2 id="分配仓库凭据" tabindex="-1">分配仓库凭据 <a class="header-anchor" href="#分配仓库凭据" aria-label="Permalink to &quot;分配仓库凭据&quot;">​</a></h2><p>仓库可以使用专用令牌、SSH 私钥或指向某个进程环境变量名称的凭据。Core 会优先使用仓库专用凭据；没有专用令牌时，GitHub 或 GitLab 仓库才会回退到全局 <code>GITHUB_TOKEN</code> 或 <code>GITLAB_TOKEN</code>。</p><p>令牌只在单次 Git 子进程环境中提供，临时凭据文件在命令结束后删除。数据库中的令牌和 SSH 私钥依赖 <code>ENCRYPTION_KEY</code> 解密。即便如此，也应遵循最小权限：只给需要的仓库读取权限，避免给写入或组织管理权限。</p><h2 id="正确签署仓库-webhook" tabindex="-1">正确签署仓库 Webhook <a class="header-anchor" href="#正确签署仓库-webhook" aria-label="Permalink to &quot;正确签署仓库 Webhook&quot;">​</a></h2><p>启用 Webhook 前，项目管理者必须设置至少 16 个字符的密钥。每个请求需要三个头：</p><ul><li><code>X-Ershu-Webhook-Timestamp</code>：与服务端时间相差不超过 5 分钟；</li><li><code>X-Ershu-Webhook-Nonce</code>：单次使用，最多 255 个字符，不能包含冒号或换行；</li><li><code>X-Ershu-Webhook-Signature</code>：用 Webhook 密钥计算的 HMAC-SHA256 十六进制摘要。</li></ul><p>签名消息必须按字节拼接：时间戳、一个 NUL 字节、Nonce、一个 NUL 字节、未经修改的原始请求正文。只签正文的旧做法不会通过。API 会把已使用的 Nonce 暂存到数据库，拒绝有效时间窗内的重复请求。</p><h2 id="收紧-mcp-网络边界" tabindex="-1">收紧 MCP 网络边界 <a class="header-anchor" href="#收紧-mcp-网络边界" aria-label="Permalink to &quot;收紧 MCP 网络边界&quot;">​</a></h2><p>MCP 在生产环境还会检查：</p><ul><li><code>MCP_BUILD_COMMIT</code> 是准确的 40 位十六进制提交号；</li><li>当前进程能读取已安装的 <code>ershu-mcp</code> 软件包版本信息；</li><li><code>MCP_ENABLE_DNS_REBINDING_PROTECTION=true</code>；</li><li><code>MCP_ALLOWED_HOSTS</code> 和 <code>MCP_ALLOWED_ORIGINS</code> 都不是空列表。</li></ul><p>这些设置保护网络入口，项目和工具权限仍由 MCP 密钥范围、账号与项目成员关系决定。不要因为网络来源已允许，就跳过接口级授权。</p><h2 id="上线前的可验证清单" tabindex="-1">上线前的可验证清单 <a class="header-anchor" href="#上线前的可验证清单" aria-label="Permalink to &quot;上线前的可验证清单&quot;">​</a></h2><ul><li>使用四份独立、稳定的服务端材料，并在备份与恢复演练中确认旧密文仍能解密。</li><li>通过 HTTPS 访问一个受保护的 API；HTTP 请求应被拒绝，HTTPS 响应应带有 HSTS 头。</li><li>从允许的前端来源完成登录和一次写操作；去掉 CSRF 请求头后，同一写操作应返回 403。</li><li>用不在 <code>GIT_ALLOWED_HOSTS</code> 中的地址创建或刷新仓库时，操作应在执行 Git 前被拒绝。</li><li>重复发送同一时间戳、Nonce、正文和签名的 Webhook；第二次应被拒绝。</li><li>用普通用户访问管理员系统设置接口，应返回 403；管理员访问才可读取。</li><li>轮换 <code>MCP_KEY_PEPPER</code> 前先制定重新签发 MCP 密钥的计划，因为旧密钥不会继续有效。</li></ul><p>这些是验收判据，不是本页声称已经执行过的测试结果。</p><h2 id="源码位置" tabindex="-1">源码位置 <a class="header-anchor" href="#源码位置" aria-label="Permalink to &quot;源码位置&quot;">​</a></h2><ul><li><code>core/src/ershu/core/config.py</code>：密钥强度、独立性和生产本地路径检查。</li><li><code>core/src/ershu/core/security.py</code>：访问令牌验证和敏感值加解密。</li><li><code>core/src/ershu/services/mcp_keys.py</code>：MCP 密钥摘要与失效规则。</li><li><code>core/src/ershu/services/repositories/git_url_security.py</code>：远程 Git 主机和地址范围检查。</li><li><code>core/src/ershu/services/repositories/workspaces.py</code>：协议、凭据选择和临时凭据处理。</li><li><code>core/src/ershu/tools/readonly_repository/workspace.py</code>：本地仓库信任规则。</li><li><code>api/src/ershu/api_main.py</code>：HTTPS、来源、CSRF 和 HSTS 处理。</li><li><code>api/src/ershu/api/web_security.py</code>：Cookie 与 CSRF 令牌。</li><li><code>api/src/ershu/api/services/opaque_auth.py</code>：OPAQUE 设置的初始化、存储和读取。</li><li><code>api/src/ershu/api/services/repositories/triggers.py</code>：Webhook 签名、时间窗和防重放。</li><li><code>mcp/src/ershu/mcp/runtime_settings.py</code>：MCP 生产网络校验。</li></ul>`,40)])])}const E=i(t,[["render",d]]);export{u as __pageData,E as default};
